{
  "findings": [
    {
      "check_id": "CKV_K8S_21",
      "title": "Ingress resource with no host defined in rule",
      "resource": "kubernetes_ingress.pass",
      "severity": "MEDIUM",
      "explanation": "The ingress resource has a rule with no host defined, potentially allowing access from any host."
    }
  ],
  "patched_code": "resource "kubernetes_ingress" "pass" {
  metadata {
    name = "example-ingress"
    namespace = "brian"
  }

  spec {
    backend {
      service_name = "MyApp1"
      service_port = 8080
    }

    rule {
      host = "example.com"
      http {
        path {
          backend {
            service_name = "MyApp1"
            service_port = 8080
          }

          path = "/app1/*"
        }

        path {
          backend {
            service_name = "MyApp2"
            service_port = 8080
          }

          path = "/app2/*"
        }
      }
    }

    tls {
      secret_name = "tls-secret"
      hosts     = ["example.com"]
    }
  }
}
",
  "fix_summary": "Added a host to the ingress rule and tls configuration to restrict access to a specific domain."
}
